import{_ as a,a0 as o,w as l,s as d,ao as r,I as p,x as e,a1 as s,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何让 Ping 的输出更简单易读 | LCTT x X-CMD","titleTemplate":false,"description":"如何让 Ping 的输出更简单易读 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何让 Ping 的输出更简单易读 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何让 Ping 的输出更简单易读 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180924 Make The Output Of Ping Command Prettier And Easier To Read","title":"如何让 Ping 的输出更简单易读","tag":"201809","desc":""},"relativePath":"201809/20180924 Make The Output Of Ping Command Prettier And Easier To Read.md","filePath":"[post].md"}'),g={name:"201809/20180924 Make The Output Of Ping Command Prettier And Easier To Read.md"};function c(h,i,u,k,b,m){const t=o("Link");return l(),d("div",null,[i[15]||(i[15]=r('<h1 id="如何让-ping-的输出更简单易读" tabindex="-1">如何让 Ping 的输出更简单易读 <a class="header-anchor" href="#如何让-ping-的输出更简单易读" aria-label="Permalink to “如何让 Ping 的输出更简单易读”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/prettyping-720x340.png" alt=""></p><p>众所周知，<code>ping</code> 命令可以用来检查目标主机是否可达。使用 <code>ping</code> 命令的时候，会发送一个 ICMP Echo 请求，通过目标主机的响应与否来确定目标主机的状态。如果你经常使用 <code>ping</code> 命令，你可以尝试一下 <code>prettyping</code>。Prettyping 只是将一个标准的 ping 工具增加了一层封装，在运行标准 <code>ping</code> 命令的同时添加了颜色和 unicode 字符解析输出，所以它的输出更漂亮紧凑、清晰易读。它是用 <code>bash</code> 和 <code>awk</code> 编写的自由开源工具，支持大部分类 Unix 操作系统，包括 GNU/Linux、FreeBSD 和 Mac OS X。Prettyping 除了美化 <code>ping</code> 命令的输出，还有很多值得注意的功能。</p><ul><li>检测丢失的数据包并在输出中标记出来。</li><li>显示实时数据。每次收到响应后，都会更新统计数据，而对于普通 <code>ping</code> 命令，只会在执行结束后统计。</li><li>可以灵活处理“未知信息”（例如错误信息），而不搞乱输出结果。</li><li>能够避免输出重复的信息。</li><li>兼容常用的 <code>ping</code> 工具命令参数。</li><li>能够由普通用户执行。</li><li>可以将输出重定向到文件中。</li><li>不需要安装，只需要下载二进制文件，赋予可执行权限即可执行。</li><li>快速且轻巧。</li><li>输出结果清晰直观。</li></ul><h3 id="安装-prettyping" tabindex="-1">安装 Prettyping <a class="header-anchor" href="#安装-prettyping" aria-label="Permalink to “安装 Prettyping”">​</a></h3><p>如上所述，Prettyping 是一个绿色软件，不需要任何安装，只要使用以下命令下载 Prettyping 二进制文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -O https://raw.githubusercontent.com/denilsonsa/prettyping/master/prettyping</span></span></code></pre></div><p>将二进制文件放置到 <code>$PATH</code>（例如 <code>/usr/local/bin</code>）中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mv prettyping /usr/local/bin</span></span></code></pre></div><p>然后对其赋予可执行权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chmod +x /usr/local/bin/prettyping</span></span></code></pre></div><p>就可以使用了。</p><h3 id="让-ping-的输出清晰易读" tabindex="-1">让 ping 的输出清晰易读 <a class="header-anchor" href="#让-ping-的输出清晰易读" aria-label="Permalink to “让 ping 的输出清晰易读”">​</a></h3><p>安装完成后，通过 <code>prettyping</code> 来 ping 任何主机或 IP 地址，就可以以图形方式查看输出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ prettyping ostechnix.com</span></span></code></pre></div><p>输出效果大概会是这样：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/prettyping-in-action.gif" alt=""></p><p>如果你不带任何参数执行 <code>prettyping</code>，它就会一直运行直到被 <code>ctrl + c</code> 中断。</p><p>由于 Prettyping 只是一个对普通 <code>ping</code> 命令的封装，所以常用的 ping 参数也是有效的。例如使用 <code>-c 5</code> 来指定 ping 一台主机的 5 次：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ prettyping -c 5 ostechnix.com</span></span></code></pre></div><p>Prettyping 默认会使用彩色输出，如果你不喜欢彩色的输出，可以加上 <code>--nocolor</code> 参数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ prettyping --nocolor ostechnix.com</span></span></code></pre></div><p>同样的，也可以用 <code>--nomulticolor</code> 参数禁用多颜色支持：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ prettyping --nomulticolor ostechnix.com</span></span></code></pre></div><p>使用 <code>--nounicode</code> 参数禁用 unicode 字符：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/prettyping-without-unicode-support.png" alt=""></p><p>如果你的终端不支持 UTF-8，或者无法修复系统中的 unicode 字体，只需要加上 <code>--nounicode</code> 参数就能轻松解决。</p><p>Prettyping 支持将输出的内容重定向到文件中，例如执行以下这个命令会将 <code>prettyping ostechnix.com</code> 的输出重定向到 <code>ostechnix.txt</code> 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ prettyping ostechnix.com | tee ostechnix.txt</span></span></code></pre></div><p>Prettyping 还有很多选项帮助你完成各种任务，例如：</p><ul><li>启用/禁用延时图例（默认启用）</li><li>强制按照终端的格式输出（默认自动）</li><li>在统计数据中统计最后的 n 次 ping（默认 60 次）</li><li>覆盖对终端尺寸的自动检测</li><li>指定 awk 解释器路径（默认：<code>awk</code>）</li><li>指定 ping 工具路径（默认：<code>ping</code>）</li></ul><p>查看帮助文档可以了解更多：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ prettyping --help</span></span></code></pre></div><p>尽管 Prettyping 没有添加任何额外功能，但我个人喜欢它的这些优点：</p><ul><li>实时统计 —— 可以随时查看所有实时统计信息，标准 <code>ping</code> 命令只会在命令执行结束后才显示统计信息。</li><li>紧凑的显示 —— 可以在终端看到更长的时间跨度。</li><li>检测丢失的数据包并显示出来。</li></ul><p>如果你一直在寻找可视化显示 <code>ping</code> 命令输出的工具，那么 Prettyping 肯定会有所帮助。尝试一下，你不会失望的。</p><hr>',37)),p("p",null,[i[1]||(i[1]=e("via: ",-1)),s(t,{href:"https://www.ostechnix.com/prettyping-make-the-output-of-ping-command-prettier-and-easier-to-read/"},{default:n(()=>[...i[0]||(i[0]=[e("https://www.ostechnix.com/prettyping-make-the-output-of-ping-command-prettier-and-easier-to-read/",-1)])]),_:1})]),p("p",null,[i[6]||(i[6]=e("作者：",-1)),s(t,{href:"https://www.ostechnix.com/author/sk/"},{default:n(()=>[...i[2]||(i[2]=[e("SK",-1)])]),_:1}),i[7]||(i[7]=e(" 选题：",-1)),s(t,{href:"https://github.com/lujun9972"},{default:n(()=>[...i[3]||(i[3]=[e("lujun9972",-1)])]),_:1}),i[8]||(i[8]=e(" 译者：",-1)),s(t,{href:"https://github.com/HankChow"},{default:n(()=>[...i[4]||(i[4]=[e("HankChow",-1)])]),_:1}),i[9]||(i[9]=e(" 校对：",-1)),s(t,{href:"https://github.com/wxy"},{default:n(()=>[...i[5]||(i[5]=[e("wxy",-1)])]),_:1})]),p("p",null,[i[12]||(i[12]=e("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...i[10]||(i[10]=[e("LCTT",-1)])]),_:1}),i[13]||(i[13]=e(" 原创编译，",-1)),s(t,{href:"https://linux.cn/"},{default:n(()=>[...i[11]||(i[11]=[e("Linux中国",-1)])]),_:1}),i[14]||(i[14]=e(" 荣誉推出",-1))])])}const C=a(g,[["render",c]]);export{x as __pageData,C as default};
